package com.crm.customer.client;
import com.fasterxml.jackson.databind.JsonNode;import org.springframework.cloud.client.discovery.DiscoveryClient;import org.springframework.stereotype.Component;import org.springframework.http.*;import org.springframework.web.client.*;import org.springframework.web.server.ResponseStatusException;import com.crm.customer.service.CustomerPersonalService;
@Component public class AssignedEmployeeDirectory {private final DiscoveryClient discovery;public AssignedEmployeeDirectory(DiscoveryClient d){discovery=d;}
 public long own(String bearer,long uid){if(bearer==null||!bearer.startsWith("Bearer ")||bearer.substring(7).isBlank())throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);JsonNode row=read(bearer);if(row==null||!row.isObject()||!row.path("userId").isTextual()||!Long.toString(uid).equals(row.path("userId").textValue())||!row.path("employeeId").isTextual())throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Invalid employee association");try{return CustomerPersonalService.id(row.path("employeeId").textValue());}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Invalid employee association");}}
 public JsonNode read(String bearer){var instances=discovery.getInstances("hr-service");if(instances.isEmpty())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Employee association unavailable");try{var f=new org.springframework.http.client.SimpleClientHttpRequestFactory(){@Override protected void prepareConnection(java.net.HttpURLConnection c,String method)throws java.io.IOException{super.prepareConnection(c,method);c.setInstanceFollowRedirects(false);}};f.setProxy(java.net.Proxy.NO_PROXY);f.setConnectTimeout(2000);f.setReadTimeout(2000);return RestClient.builder().requestFactory(f).baseUrl(instances.getFirst().getUri().toString()).build().get().uri("/api/employee-associations/me").header(HttpHeaders.AUTHORIZATION,bearer).retrieve().onStatus(s->s.is3xxRedirection(),(a,b)->{throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE);}).body(JsonNode.class);}catch(RestClientResponseException e){int s=e.getStatusCode().value();throw new ResponseStatusException(s==401?HttpStatus.UNAUTHORIZED:s==403?HttpStatus.FORBIDDEN:s==404?HttpStatus.NOT_FOUND:s>=500?HttpStatus.SERVICE_UNAVAILABLE:HttpStatus.BAD_GATEWAY,"Employee association unavailable");}catch(ResourceAccessException e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE);}catch(RestClientException e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY);}}
}
